// GENERATED by tools/primh/primh.py; live GNU is not needed to run this test.
use romacs_vm::Vm;
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::collections::BTreeSet;

fn hash(bytes: &[u8]) -> String {
    Sha256::digest(bytes).iter().map(|b| format!("{b:02x}")).collect()
}

fn classify(expected: &str, actual: &str) -> &'static str {
    if expected == actual { return "PASS"; }
    if actual.starts_with("VM-ERROR") {
        return if actual.contains("print") { "PRINTER" } else { "VM-INTERNAL" };
    }
    if actual.starts_with("(sig (void-function") { return "MISSING"; }
    let e_sig = expected.starts_with("(sig ");
    let a_sig = actual.starts_with("(sig ");
    if e_sig && a_sig {
        let condition = |s: &str| s[6..].split(' ').next().unwrap().trim_end_matches(')').to_owned();
        return if condition(expected) == condition(actual) { "DATA" } else { "CONDITION" };
    }
    if e_sig != a_sig { return "SIGNAL-VS-VALUE"; }
    if expected.contains("#<") || expected.contains("#[") || actual.contains("#<") { return "PRINTER"; }
    "VALUE"
}

fn validate_declaration(spec: &Value) {
    let manifest: Value = serde_json::from_str(include_str!(concat!(env!("OUT_DIR"), "/primitives.json"))).unwrap();
    let current = manifest.as_array().unwrap().iter()
        .find(|m| m["name"] == spec["name"])
        .expect("declaration name missing from current runtime manifest");
    assert_eq!(spec["arity"], serde_json::json!([current["min"], current["max"]]), "declaration arity stale");
    assert_eq!(spec["effect"].as_str().unwrap(), current["effect"].as_str().unwrap().to_lowercase(), "declaration effect stale");
    assert_eq!(spec["gnu_def"], current["gnu"], "declaration gnu stale");
    assert_eq!(spec["rust"], current["rust"], "declaration rust stale");
}

fn replay(ev: &str, spec: &[u8]) {
    validate_declaration(&serde_json::from_slice(spec).unwrap());
    let ev: Value = serde_json::from_str(ev).unwrap();
    assert_eq!(ev["protocol"], "primh-v1");
    assert_eq!(ev["spec_sha256"], hash(spec), "declaration changed; re-record");
    assert_eq!(ev["generator_sha256"], hash(include_bytes!("../tools/primh/primh.py")), "generator changed; re-record");
    assert_eq!(ev["driver_sha256"], hash(include_bytes!("../tools/primh/gnu_driver.el")), "driver changed; re-record");
    assert_eq!(ev["domains_sha256"], hash(include_bytes!("../tools/primh/domains.json")), "domains changed; re-record");
    assert_eq!(ev["replay_sha256"], hash(include_bytes!("../tools/primh/replay.rs.in")), "replay changed; re-record");
    let pinned = ev["pinned"].as_object().cloned().unwrap_or_default();
    let rows = ev["cases"].as_array().unwrap();
    let ids: BTreeSet<_> = rows.iter().map(|r| r["id"].as_str().unwrap()).collect();
    assert_eq!(ids.len(), rows.len(), "duplicate case IDs");
    let mut bad = Vec::new();
    for key in pinned.keys() {
        if !ids.contains(key.as_str()) { bad.push(format!("UNKNOWN PIN: {key}")); }
    }
    for row in rows {
        let id = row["id"].as_str().unwrap();
        let pin = pinned.get(id);
        if row["expected"] == "GNU-TIMEOUT" {
            if pin.is_some() { bad.push(format!("STALE PIN: {id} (excluded GNU timeout)")); }
            continue;
        }
        let mut vm = Vm::new();
        vm.set_collection_floor(1);
        let src = row["source"].as_str().unwrap();
        let actual = match vm.eval_source(src) {
            Ok(v) => v.display().map(|s| serde_json::from_str::<String>(&s).unwrap_or(s)).unwrap_or_else(|e| format!("VM-ERROR {e}")),
            Err(e) => format!("VM-ERROR {e}"),
        };
        let expected = row["expected"].as_str().unwrap();
        let same = actual == expected || row["gnu_regime_variant"].as_str() == Some(actual.as_str());
        match (same, pin) {
            (true, Some(c)) => bad.push(format!("STALE PIN ({c}): {id}: {src}")),
            (false, None) => bad.push(format!("NEW DIVERGENCE ({}): {id}: {src}\n  GNU {expected}\n  VM2 {actual}", classify(expected, &actual))),
            (false, Some(c)) if c.as_str() != Some(classify(expected, &actual)) => bad.push(format!("CHANGED PIN ({c} -> {}): {id}", classify(expected, &actual))),
            _ => {}
        }
    }
    assert!(bad.is_empty(), "{} {}:\n{}", bad.len(), ev["primitive"], bad.join("\n"));
}

// Harness mutation checks use an actual live-GNU catalog row, not invented
// expected outcomes. Both run the real VM with collection floor 1.
fn smoke_evidence() -> Value {
    let mut ev: Value = serde_json::from_str(include_str!("../tools/primh/evidence/cdr-safe.json")).unwrap();
    let row = ev["cases"].as_array().unwrap().iter()
        .find(|r| r["family"] == "printer" && r["expected"] == "(ok nil)")
        .expect("live GNU nil printer row").clone();
    ev["cases"] = serde_json::json!([row]);
    ev["pinned"] = serde_json::json!({});
    ev
}

#[test]
fn primh_harness_declaration_mutations() {
    let spec: Value = serde_json::from_slice(include_bytes!("../tools/primh/specs/cdr-safe.json")).unwrap();
    validate_declaration(&spec);
    for (field, value, diagnostic) in [
        ("name", serde_json::json!("not-registered"), "declaration name"),
        ("arity", serde_json::json!([0, 1]), "declaration arity"),
        ("arity", serde_json::json!([1, 2]), "declaration arity"),
        ("effect", serde_json::json!("global"), "declaration effect"),
        ("gnu_def", serde_json::json!("wrong.c:1"), "declaration gnu"),
        ("rust", serde_json::json!("wrong.rs:1"), "declaration rust"),
    ] {
        let mut mutant = spec.clone();
        mutant[field] = value;
        let failure = std::panic::catch_unwind(|| validate_declaration(&mutant))
            .expect_err("stale declaration mutant survived");
        let message = failure.downcast_ref::<String>().map(String::as_str)
            .or_else(|| failure.downcast_ref::<&str>().copied()).unwrap_or("");
        assert!(message.contains(diagnostic), "wrong mutation failure: {message}");
    }
}

#[test]
fn primh_harness_smoke() {
    replay(&smoke_evidence().to_string(), include_bytes!("../tools/primh/specs/cdr-safe.json"));
}

#[test]
#[should_panic(expected = "NEW DIVERGENCE")]
fn primh_harness_new_mutation() {
    let mut ev = smoke_evidence();
    ev["cases"][0]["source"] = serde_json::json!("(prin1-to-string (list 'ok t))");
    replay(&ev.to_string(), include_bytes!("../tools/primh/specs/cdr-safe.json"));
}

#[test]
#[should_panic(expected = "STALE PIN")]
fn primh_harness_stale_mutation() {
    let mut ev = smoke_evidence();
    let id = ev["cases"][0]["id"].as_str().unwrap().to_owned();
    ev["pinned"][id] = serde_json::json!("VALUE");
    replay(&ev.to_string(), include_bytes!("../tools/primh/specs/cdr-safe.json"));
}

